#!/usr/bin/env python3
"""Optional local reading copy. Canonical technical content remains in Markdown."""
from pathlib import Path
import html,re
import mistune
root=Path(__file__).resolve().parent.parent
names=['START_HERE','IMPLEMENTATION_STATUS','ARCHITECTURE','SDK_API','POWER_AND_RELIABILITY','DATA_AND_PRIVACY','DISTRIBUTION','RELEASE_PLAYBOOK','RESEARCH','USER_JOURNEYS','VERIFICATION']
markdown=mistune.create_markdown(escape=False,plugins=['table','url'])
sections=[];navigation=[]
for name in names:
 file=root/'docs'/f'{name}.md';text=file.read_text();title=text.splitlines()[0].lstrip('# ');anchor=name.lower().replace('_','-')
 body=markdown(text)
 def link(match):
  url=match.group(1)
  if re.match(r'^[a-z]+:',url) or url.startswith('#'):return match.group(0)
  path=(file.parent/url.split('#')[0]).resolve()
  if path.parent==root/'docs' and path.stem in names:return 'href="#'+path.stem.lower().replace('_','-')+'"'
  try:relative=path.relative_to(root)
  except ValueError:return match.group(0)
  return 'href="https://github.com/phillipsk/RoadSignalLab/'+('tree' if path.is_dir() else 'blob')+'/main/'+str(relative)+'"'
 body=re.sub(r'href="([^"]+)"',link,body)
 sections.append(f'<section id="{anchor}">{body}</section>');navigation.append(f'<a href="#{anchor}">{html.escape(title)}</a>')
shots=[('01-welcome','Welcome · local lab'),('05-trip-detail','Persisted synthetic trip'),('07-power-model','Power ownership model'),('10-local-acknowledgment','Local mock acknowledgment'),('12-cmt-mock-boundary','CMT mock boundary'),('16-device-session-active','Actual location FGS')]
gallery=''.join(f'<figure><img src="screenshots/{name}.png" alt="{label}"><figcaption>{label}</figcaption></figure>' for name,label in shots)
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RoadSignal Lab · SDK engineering report</title><style>\n:root{--ink:#142d3b;--paper:#f4f5ef;--line:#dce1d8;--lime:#bce877}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}nav{position:fixed;inset:0 auto 0 0;width:250px;padding:30px 22px;background:var(--ink);color:#fff;overflow:auto}nav strong{font-size:23px;color:var(--lime)}nav a{display:block;color:#d9e7e3;font-size:13px;line-height:1.5;margin:15px 0;text-decoration:none}main{max-width:1320px;margin-left:250px;padding:42px 5vw 80px}header{border-bottom:1px solid var(--line);padding-bottom:30px}h1{font-size:36px;line-height:1.15;letter-spacing:-1px}h2{font-size:25px;margin-top:35px}h3{font-size:20px}a{color:#1d736d}section{scroll-margin-top:25px;background:#fff;border:1px solid var(--line);border-radius:24px;padding:28px;margin:28px 0}section h1{font-size:30px}table{display:block;overflow-x:auto;border-collapse:collapse;font-size:13px}th,td{border:1px solid var(--line);padding:10px;vertical-align:top}th{background:#e8eee1;text-align:left}pre{background:var(--ink);color:#e5efeb;padding:18px;border-radius:14px;overflow:auto;font:13px/1.7 ui-monospace,monospace}code{font-family:ui-monospace,monospace;font-size:.88em;overflow-wrap:anywhere}blockquote{border-left:4px solid var(--lime);margin:20px 0;padding:12px 20px;background:#edf2e7}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:26px}figure{margin:0;background:#fff;padding:12px;border-radius:20px;border:1px solid var(--line)}figure img{width:100%;height:auto;border-radius:10px}figcaption{font-size:12px;margin-top:9px;color:#5f716f}.eyebrow{color:#237a70;font-size:11px;letter-spacing:2px;font-weight:700}.pill{display:inline-block;background:var(--lime);padding:6px 14px;border-radius:30px;font-size:12px;font-weight:700}.small{font-size:13px;color:#5f716f}@media(max-width:850px){nav{position:static;width:auto}nav a{display:inline-block;margin:8px 12px 3px 0}main{margin:0;padding:24px 18px}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}section{padding:20px}h1{font-size:31px}}@media print{nav{display:none}main{margin:0;padding:0}section{break-before:page;border:0;padding:0}.gallery{grid-template-columns:repeat(3,1fr)}a{color:inherit}pre{white-space:pre-wrap}}\n</style></head><body><nav><strong>◉ roadsignal</strong><p class="small" style="color:#b9cdc6">Android SDK field lab</p>'+''.join(navigation)+'<a href="https://github.com/phillipsk/RoadSignalLab">GitHub source &amp; evidence ↗</a><a href="https://github.com/phillipsk/RoadSignalLab/blob/main/docs/RESEARCH.md">Primary-source research ledger ↗</a></nav><main><header><div class="eyebrow">ORIGINAL SDK · COMPOSE HOST · DISTRIBUTION LAB</div><h1>Understand the drive.<br>Own the engineering.</h1><p>A technical guide to an Android telematics SDK example, its Compose host, and the distribution pipeline. Canonical Markdown, native screenshots, source and executable checks are in GitHub.</p><span class="pill">Independent SDK exploration</span><p class="small">CMT integration is a labeled mock. Replay is synthetic, power comparisons are modeled, and no emergency response or real upload occurs. Mermaid diagrams below are preserved as source; GitHub renders their canonical Markdown versions.</p></header>'+f'<div class="gallery">{gallery}</div>'+''.join(sections)+'<footer class="small">Prepared November 4, 2026. Review the verification evidence and implementation boundaries when evaluating the SDK. No affiliation with Cambridge Mobile Telematics is implied.</footer></main></body></html>'
(root/'docs/engineering-report.html').write_text(page)
print('Portable reading copy: docs/engineering-report.html')
